head.script:
scwin.onpageload = function() {
    console.log("[tabControl_main_wframeMode.xml] scwin.onpageload");
    //scwin.btn_trigger1_onclick();
    //$w.setTimeout(function(){scwin.btn_trigger1_onclick();}, {delay:1000, key:"timeout1"});
};
scwin.onpageunload = function() {};
scwin.addTab = function(tabId) {
    var tabOpt = {
        label: tabId,
        closable: false,
        addTabIndex: 0
    };
    var contOpt = {
        frameMode: "wframe",
        scope: true,
        src: tabId + ".xml",
        alwaysDraw: false,
        title: tabId
    };
    tac_main.addTab(tabId, tabOpt, contOpt);
};
scwin.btn_trigger1_onclick = function(e) {
    var tabId = "tab" + scwin.tabIndex;
    scwin.addTab(tabId);
    tac_main.setSelectedTabIndex(tabId);
    scwin.tabIndex++;
};
scwin.tac_main_ondrawcomplete = function(tabID, idx, userID) {
    console.log("scwin.tac_main_ondrawcomplete");
};
scwin.tac_main_ontabload = function(tabID, idx, userID) {
    console.log("scwin.tac_main_ontabload");
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.tabIndex = 1;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
